const crypto = require('crypto');
const e = $input.first().json;

const workflow = (e.workflow && e.workflow.name) || 'unknown workflow';
const executionId = (e.execution && e.execution.id) ? String(e.execution.id) : `trigger-${(e.workflow && e.workflow.id) || 'unknown'}-${Date.now()}`;
const node = (e.execution && e.execution.lastNodeExecuted) || (e.trigger && e.trigger.error && e.trigger.error.node && e.trigger.error.node.name) || null;
const rawMessage = (e.execution && e.execution.error && e.execution.error.message) || (e.trigger && e.trigger.error && e.trigger.error.message) || 'Unknown error';
const message = String(rawMessage).replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[email]').slice(0, 500);

console.error(`[workflow-error] ${workflow} / ${node || '-'} / execution ${executionId}: ${message}`);

const body = JSON.stringify({ executionId, workflow, node, message });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET).update(timestamp + '.' + body).digest('hex');

return [{ json: { executionId, workflow, node, message, body, timestamp, signature } }];
